WITH cleaned AS (SELECT *, DATEDIFF(CURRENT_DATE(), reading_ts) / 7 AS weeks_since_reading_ts, pressure * humidity AS pressure_times_humidity FROM device_readings WHERE reading_ts >= DATE '2025-09-01'), filtered AS (SELECT *, weeks_since_reading_ts / NULLIF(pressure_times_humidity, 0) AS weeks_since_reading_ts_per_pressure_times_humidity, TRIM(device_code) AS clean_device_code FROM cleaned WHERE reading_ts >= TIMESTAMP '2025-09-01 06:00:00' AND pressure <= 997), flagged AS (SELECT *, CASE WHEN LAG(reading_ts) OVER (PARTITION BY device_code ORDER BY reading_ts, id) IS NULL OR reading_ts > LAG(reading_ts) OVER (PARTITION BY device_code ORDER BY reading_ts, id) + INTERVAL 15 MINUTES THEN 1 ELSE 0 END AS new_group_flag FROM filtered), sessionized AS (SELECT id, device_code, reading_ts, temp_c, firmware, weeks_since_reading_ts, clean_device_code, SUM(new_group_flag) OVER (PARTITION BY device_code ORDER BY reading_ts, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS burst_id FROM flagged), ranked AS (SELECT id, temp_c, clean_device_code, burst_id FROM (SELECT *, ROW_NUMBER() OVER (PARTITION BY device_code ORDER BY reading_ts DESC, id) AS row_num FROM sessionized) t WHERE row_num = 1), scored AS (SELECT id, clean_device_code, LEAD(burst_id) OVER w_hist AS next_burst_id, LAG(temp_c) OVER w_hist AS prev_temp_c, LEAD(temp_c) OVER w_hist AS next_temp_c, ROW_NUMBER() OVER w_hist AS event_seq FROM ranked WINDOW w_hist AS (ORDER BY temp_c, id)) SELECT id, clean_device_code, next_burst_id, prev_temp_c, next_temp_c, event_seq FROM scored ORDER BY next_burst_id;
